-- Consented first-party analytics event stream with 90-day expiry.
create table if not exists public.analytics_events(id uuid primary key default gen_random_uuid(),event_name text not null check(event_name in('page_view','page_exit','click','scroll_depth','form_start','form_submit','form_validation_error','form_abandon','contact_action','js_error')),page_path text not null check(char_length(page_path)<=500),page_title text check(page_title is null or char_length(page_title)<=160),element_id text check(element_id is null or char_length(element_id)<=100),element_label text check(element_label is null or char_length(element_label)<=80),value numeric check(value is null or(value>=0 and value<=1000000)),visitor_uuid text check(visitor_uuid is null or char_length(visitor_uuid)<=64),session_uuid text check(session_uuid is null or char_length(session_uuid)<=64),device_category text not null default 'other' check(device_category in('mobile','tablet','desktop','other')),consent_state text not null default 'granted' check(consent_state='granted'),created_at timestamptz not null default now(),retention_until timestamptz not null default(now()+interval '90 days'));
create index if not exists analytics_events_created_idx on public.analytics_events(created_at desc);
create index if not exists analytics_events_page_idx on public.analytics_events(page_path,created_at desc);
create index if not exists analytics_events_session_idx on public.analytics_events(session_uuid,created_at desc);
create index if not exists analytics_events_event_idx on public.analytics_events(event_name,created_at desc);
alter table public.analytics_events enable row level security;
revoke all on public.analytics_events from anon,authenticated;grant insert on public.analytics_events to anon,authenticated;grant select on public.analytics_events to authenticated;
drop policy if exists "Visitors insert consented analytics events" on public.analytics_events;create policy "Visitors insert consented analytics events" on public.analytics_events for insert to anon,authenticated with check(consent_state='granted' and char_length(page_path)<=500);
drop policy if exists "Karma admins read analytics events" on public.analytics_events;create policy "Karma admins read analytics events" on public.analytics_events for select to authenticated using(private.is_karma_admin());
create or replace function public.purge_expired_website_analytics() returns bigint language plpgsql security definer set search_path=public as $$ declare deleted_count bigint; begin delete from public.analytics_events where retention_until<now(); get diagnostics deleted_count=row_count; return deleted_count; end $$;revoke all on function public.purge_expired_website_analytics() from public,anon,authenticated;
-- pg_cron schedules cleanup; if unavailable, schedule the purge function daily in Supabase.
do $$ begin if exists(select 1 from pg_extension where extname='pg_cron') then execute $schedule$select cron.schedule('karma-website-analytics-retention','30 3 * * *','select public.purge_expired_website_analytics()')$schedule$;end if;exception when others then raise notice 'Retention cron unavailable: schedule purge function daily.';end $$;
